class Solution:
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next

    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        dummy = ListNode(0)
        curr = dummy
        for list_ in lists:
            while list_ is not None:
                curr.next = list_.next
                list_ = list_.next
                curr = curr.next
        return dummy.next

