            graph[b][a] = True
        return max_degree(graph) == n // 2

def max_degree(graph):
    degree = [0] * (n + 1)
    for i in range(n):
        for j in graph[i]:
            degree[j] += 1
    for i in range(n):
        for j in range(n):
            if graph[i][j]:
                degree[i] += degree[j]
    return max(degree)

