    class Solution:
        def checkSubarraySum(self, nums: List[int], k: int) -> bool:
            seen = {0: -1}
            current_sum = 0
            for i in range(len(nums)):
                current_sum += nums[i]
                mod = current_sum % k
                if mod in seen:
                    if i - seen[mod] >= 2:
                        return True
                else:
                    seen[mod] = i
            return False

