    class Solution:
        def checkInclusion(self, s1: str, s2: str) -> bool:
            len1, len2 = len(s1), len(s2)
            if len1 > len2:
                return False

            count_s1 = [0] * 26
            count_window = [0] * 26

            for c in s1:
                count_s1[ord(c) - ord('a')] += 1

            for i in range(len1):
                c = s2[i]
                count_window[ord(c) - ord('a')] += 1

            if count_s1 == count_window:
                return True

            for i in range(len1, len2):
                outgoing = s2[i - len1]
                count_window[ord(outgoing) - ord('a')] -= 1
                incoming = s2[i]
                count_window[ord(incoming) - ord('a')] += 1
                if count_s1 == count_window:
                    return True

            return False

class Solution:
    def findIntegers(self, n: int) -> int:
            bits = list(map(int, bin(n)[2:]))
            m = len(bits)


            @lru_cache(maxsize=None)
            def dp(pos, prev, tight):
                if pos == m:
                    return 1
                res = 0
                max_d = bits[pos] if tight else 1
                for d in range(0, max_d + 1):
                    new_tight = tight and (d == max_d)
                    if prev and d == 1:
                        continue  # Skip if two consecutive ones
                    res += dp(pos + 1, d, new_tight)
                return res

            return dp(0, 0, True)
    ```

