class Solution:
    def isPossible(self, nums: List[int]) -> bool:
        from collections import defaultdict
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        count = defaultdict(int)

        for x in nums:
            if freq[x] == 0:
                continue
            freq[x] -= 1

            if count[x-1] > 0:
                count[x-1] -= 1
                count[x] += 1
            else:
                if freq.get(x+1, 0) > 0 and freq.get(x+2, 0) > 0:
                    freq[x+1] -= 1
                    freq[x+2] -= 1
                    count[x+2] += 1
                else:
                    return False
        return True

