class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        count_ones = sum(nums)
        n = len(nums)
        if count_ones == 0 or count_ones == n:
            return 0

        doubled = nums + nums
        min_swaps = float('inf')
        current_zeros = 0

        # Initialize the first window
        for i in range(count_ones):
            if doubled[i] == 0:
                current_zeros += 1
        min_swaps = current_zeros

        # Slide the window
        for i in range(1, n):
            if doubled[i-1] == 0:
                current_zeros -= 1
            if doubled[i + count_ones -1] == 0:
                current_zeros += 1
            if current_zeros < min_swaps:
                min_swaps = current_zeros

        return min_swaps

