class Solution:
    def maximumEvenSplit(self, finalSum: int) -> List[int]:
        if finalSum % 2 != 0:
            return []
        s = finalSum
        k = int(((4 * s + 1) ** 0.5 - 1) // 2)
        while k * (k + 1) > s:
            k -= 1
        while (k + 1) * (k + 2) <= s:
            k += 1
        R = s - k * (k + 1)
        if R == 0:
            return list(range(2, 2 * k + 1, 2))
        elif R > 2 * k:
            res = list(range(2, 2 * k + 1, 2))
            res.append(R)
            return res
        else:
            res = list(range(2, 2 * (k - 1) + 1, 2))
            res.append(2 * k + R)
            return res

