class Solution:
    import math

    def repairCars(self, ranks: List[int], cars: int) -> int:
        if not ranks:
            return 0
        max_rank = max(ranks)
        low = 0
        high = max_rank * cars * cars

        while low < high:
            mid = (low + high) // 2
            total = 0
            for r in ranks:
                if r == 0:
                    continue
                max_n = self.math.isqrt(mid // r)
                total += max_n
                if total >= cars:
                    break
            if total >= cars:
                high = mid
            else:
                low = mid + 1
        return low

