class AllOne:

    def __init__(self):
        self.counts = {}
        self.keys_by_count = {}

    def inc(self, key: str) -> None:
        if key not in self.counts:
            self.counts[key] = 1
            self.keys_by_count.setdefault(1, []).append(key)
        else:
            self.counts[key] += 1
            self.keys_by_count[self.counts[key]] = self.keys_by_count.get(self.counts[key], [])
            self.keys_by_count[self.counts[key] - 1].remove(key)
            if not self.keys_by_count[self.counts[key] - 1]:
                del self.keys_by_count[self.counts[key] - 1]

    def dec(self, key: str) -> None:
        if key in self.counts:
            count = self.counts[key]
            if count == 1:
                del self.counts[key]
                self.keys_by_count[count].remove(key)
                if not self.keys_by_count[count]:
                    del self.keys_by_count[count]
            else:
                self.counts[key] -= 1
                self.keys_by_count[self.counts[key]].append(key)
                self.keys_by_count[count].remove(key)
                if not self.keys_by_count[count]:
                    del self.keys_by_count[count]

    def getMaxKey(self) -> str:
        if self.keys_by_count:
            return self.keys_by_count[max(self.keys_by_count.keys())][0]
        return ""

    def getMinKey(self) -> str:
        if self.keys_by_count:
            return self.keys_by_count[min(self.keys_by_count.keys())][0]

