class Solution:
    def compress(self, chars: List[str]) -> int:
        if not chars:
            return 0
        i = 0
        j = 1
        while j < len(chars):
            if chars[i] == chars[j]:
                j += 1
            else:
                if j - i > 1:
                    chars[i + 1:j] = [str(j - i)]
                    i += j - i + 1
                else:
                    i += 1
                j = i + 1
        if j - i > 1:
            chars[i + 1:j] = [str(j - i)]
        return i + 1
