class Solution:
    def possibleBipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        graph = [[] for _ in range(n + 1)]
        for a, b in dislikes:
            graph[a].append(b)
            graph[b].append(a)
        colors = [0] * (n + 1)
        for i in range(1, n + 1):
            if colors[i] == 0:
                if not self.dfs(graph, colors, i, 1):
                    return False
        return True

    def dfs(self, graph, colors, node, color):
        colors[node] = color
        for neighbor in graph[node]:
            if colors[neighbor] == color:
                return False
            if colors[neighbor] == 0 and not self.dfs(graph, colors, neighbor, -color):
                return False
        return True
