class Solution:
    def clumsy(self, n: int) -> int:
        result = 1
        for i in range(n, 0, -1):
            if (n - i) % 4 == 1:
                result *= i
            elif (n - i) % 4 == 2:
                result //= i
            elif (n - i) % 4 == 3:
                result += i
            else:
                result -= i
        return result
