class MKAverage:

    def __init__(self, m: int, k: int):
        self.stream = []
        self.m = m
        self.k = k

    def addElement(self, num: int) -> None:
        self.stream.append(num)

    def calculateMKAverage(self) -> int:
        if len(self.stream) < self.m:
            return -1
        else:
            container = sorted(self.stream[-self.m:])
            container = container[k: -k]
            return int(sum(container) / len(container))
```
