class Solution:
    def distinctSequences(self, n: int) -> int:
        mod = 10**9 + 7
        dp = [[0 for _ in range(7)] for _ in range(n + 1)]
        dp[0][1] = 1
        for i in range(1, n + 1):
            for j in range(1, 7):
                for k in range(1, 7):
                    if gcd(j, k) == 1:
                        dp[i][j] = (dp[i][j] + dp[i - 1][k]) % mod
        return sum(dp[n]) % mod

    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a
```

