class Solution:
    def minSumSquareDiff(self, nums1: List[int], nums2: List[int], k1: int, k2: int) -> int:
        n = len(nums1)
        diff = [(nums1[i] - nums2[i]) ** 2 for i in range(n)]
        diff.sort()
        k1, k2 = k1, k2
        for i in range(min(k1, k2)):
            diff[i] -= 2
        for i in range(min(k1, k2), min(k1, k2) + min(k1, k2)):
            diff[i] -= 2
        return sum(diff)
