class Solution:
    def canChange(self, start: str, target: str) -> bool:
        l_pos = [i for i, c in enumerate(start) if c == 'L']
        r_pos = [i for i, c in enumerate(start) if c == 'R']
        for i in range(len(start)):
            if start[i] == '_' and target[i] == 'L':
                if i < l_pos[0]:
                    return False
            if start[i] == '_' and target[i] == 'R':
                if i > r_pos[-1]:
                    return False
            if start[i] == 'L' and target[i] == 'L' and l_pos[0] != i:
                return False
            if start[i] == 'R' and target[i] == 'R' and r_pos[-1] != i:
                return False
        return True
```
