                s[i] = chr(ord('a') + min_cost)
        return ''.join(s)

    def calculate_cost(self, s: str, t: str) -> int:
        cost = 0
        for i in range(len(s)):
            if s[i] == t[i % len(t)]:
                cost += 1
        return cost
