class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        mod = 10**9 + 7
        dp = [[0 for _ in range(limit + 1)] for _ in range(zero + 1)]
        dp[0][0] = 1
        for i in range(1, zero + 1):
            for j in range(limit + 1):
                dp[i][j] = dp[i - 1][j]
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod
        return dp[zero][one]
