class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = int(s, 2)
        count = 0
        for i in range(1, n):
            num_set_bits = bin(i).count("1")
            if self.isKReducible(i, k):
                count += 1
        return count % (10**9 + 7)

    def isKReducible(self, num, k):
        while k > 0 and num != 1:
            num_set_bits = bin(num).count("1")
            num = num_set_bits
            k -= 1
        return num == 1
