class Solution:
    def minStable(self, nums: List[int], maxC: int) -> int:
        n = len(nums)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            for j in range(i):
                if gcd(nums[j], nums[i - 1]) >= 2:
                    dp[i] = max(dp[i], dp[j] + 1)
        for i in range(n):
            for j in range(maxC):
                nums[i] = max(1, nums[i] - 1)
                dp[i + 1] = max(dp[i + 1], dp[i] + 1)
        return max(dp)

    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a
