class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
            def count_digits(cur, n):
                step = 0
                while cur <= n:
                    step += min(n + 1, cur * 10) - cur
                    cur *= 10
                return step

            cur = 1
            k -= 1
            while k > 0:
                step = count_digits(cur, n)
                if k >= step:
                    k -= step
                    cur += 1
                else:
                    k -= 1
                    cur *= 10
            return cur
