                    i += 1
                elif formula[i] == ')':
                    top = stack.pop()
                    i += 1
                    start = i
                    while i < n and formula[i].isdigit():
                        i += 1
                    multiplier = int(formula[start:i] or 1)
                    for name, count in top.items():
                        stack[-1][name] = stack[-1].get(name, 0) + count * multiplier
                else:
                    start = i
                    i += 1
                    while i < n and formula[i].islower():
                        i += 1
                    name = formula[start:i]
                    start = i
                    while i < n and formula[i].isdigit():
                        i += 1
                    count = int(formula[start:i] or 1)
                    stack[-1][name] = stack[-1].get(name, 0) + count
            result = []
            for name in sorted(stack[-1]):
                result.append(name)
                if stack[-1][name] > 1:
                    result.append(str(stack[-1][name]))
            return ''.join(result)
    ```

class Solution:
    def crackSafe(self, n: int, k: int) -> str:
            result = "0" * n
            visited = set()
            for _ in range(k ** n):
                prefix = result[-(n - 1):]
                for i in range(k - 1, -1, -1):
                    combination = prefix + str(i)
                    if combination not in visited:
                        visited.add(combination)
                        result += str(i)
                        break
