class Solution:
    def reachNumber(self, target: int) -> int:
            target = abs(target)
            low, high = 1, target
            res = 0
            while low <= high:
                mid = (low + high) // 2
                total = mid * (mid + 1) // 2
                if total >= target and (total - target) % 2 == 0:
                    res = mid
                    break
                elif total < target:
                    low = mid + 1
                else:
                    high = mid - 1
            return res
    ```

class Solution:
    def minSwapsCouples(self, row: List[int]) -> int:
            n = len(row) // 2
            d = {v: i for i, v in enumerate(row)}
            ans = 0
            for i in range(n):
                a, b = 2 * i, 2 * i + 1
                if row[a] % 2 == 0 and row[b] == row[a] + 1 or row[b] % 2 == 1 and row[a] == row[b] - 1:
                    continue
                if row[a] % 2 == 0:
                    target = row[a] + 1
                else:
                    target = row[a] - 1
                target_index = d[target]
                row[b], row[target_index] = row[target_index], row[b]
                d[row[b]], d[row[target_index]] = d[row[target_index]], d[row[b]]
                ans += 1
            return ans
    ```

