class Solution:
    def doesAliceWin(self, s: str) -> bool:
            vowels = set('aeiou')
            n = len(s)
            dp = [[-1] * (n + 1) for _ in range(n + 1)]

            def dfs(start, end):
                if dp[start][end] != -1:
                    return dp[start][end]
                count = sum(1 for i in range(start, end) if s[i] in vowels)
                if count % 2 == 1:
                    dp[start][end] = 1
                    return 1
                if start == end:
                    dp[start][end] = 0
                    return 0
                win = False
                for i in range(start + 1, end + 1):
                    if dfs(start, i - 1) == 0 or dfs(i, end) == 0:
                        win = True
                        break
                dp[start][end] = 1 if win else 0
                return dp[start][end]

            return dfs(0, n) == 1
    ```

