            diff = 0
            for c1, c2 in zip(s1, s2):
                if c1 != c2:
                    diff += 1
                if diff > 1:
                    return False
            return True

        def get_sequence(word1, word2):
            sequence = []
            i = 0
            for c in word2:
                while i < len(word1) and word1[i] != c:
                    i += 1
                if i == len(word1):
