class Solution:
    def primePalindrome(self, n: int) -> int:
        def is_prime(num: int) -> bool:
            if num < 2 or num % 2 == 0:
                return num == 2
            i = 3
            while i * i <= num:
                if num % i == 0:
                    return False
                i += 2
            return True

        if n <= 2:
            return 2
        if n % 2 == 0:
            n += 1

        while True:
            if str(n) == str(n)[::-1] and is_prime(n):
                return n
            n += 2
            if 10**7 < n < 10**8:
                n = 10**8 + 1
