class Solution:
    def removeZeroSumSublists(self, head: Optional[ListNode]) -> Optional[ListNode]:
            dummy = ListNode(0)
            dummy.next = head
            prefix_sum = 0
            seen = {0: dummy}
            while head:
                prefix_sum += head.val
                if prefix_sum in seen:
                    node = seen[prefix_sum]
                    tmp = node.next
                    tmpPrefix = prefix_sum + tmp.val
                    while tmp != head:
                        del seen[tmpPrefix]
                        tmp = tmp.next
                        tmpPrefix = tmp.val + tmpPrefix
                    node.next = head.next
                else:
                    seen[prefix_sum] = head
                head = head.next
            return dummy.next
    ```

