class Solution:
    def latestTimeCatchTheBus(self, buses: List[int], passengers: List[int], capacity: int) -> int:
            buses.sort()
            passengers.sort()
            i = 0
            for bus in buses:
                count = capacity
                while count > 0 and i < len(passengers) and passengers[i] <= bus:
                    count -= 1
                    i += 1
            latest = buses[-1] if count > 0 else passengers[i - 1]
            while i > 0 and passengers[i - 1] == latest:
                i -= 1
                latest -= 1
            return latest
    ```

class Solution:
    def minSumSquareDiff(self, nums1: List[int], nums2: List[int], k1: int, k2: int -> int:
            diff = [abs(a - b) for a, b in zip(nums1, nums2)]
            total_k = k1 + k2
            max_heap = [-d for d in diff]
            heapq.heapify(max_heap)
            while total_k > 0 and max_heap[0] != 0:
                max_diff = -heapq.heappop(max_heap)
                heapq.heappush(max_heap, -(max_diff - 1))
                total_k -= 1
            return sum(d ** 2 for d in [-x for x in max_heap])
    ```

