            self.chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
            self.base = 'http://tinyurl.com/'

        def _generate_code(self):
            return ''.join(random.choices(self.chars, k=6))

        def encode(self, longUrl: str) -> str:
            if longUrl in self.long_to_short:
                return self.base + self.long_to_short[longUrl]
            while True:
                code = self._generate_code()
                if code not in self.short_to_long:
                    break
            self.short_to_long[code] = longUrl
            self.long_to_short[longUrl] = code
            return self.base + code

        def decode(self, shortUrl: str) -> str:
            code = shortUrl.replace(self.base, '')
            return self.short_to_long[code]

class Solution:
    class RecentCounter:

        def __init__(self):
            self.requests = []

        def ping(self, t: int) -> int:
            self.requests.append(t)
            left = 0
            while self.requests[left] < t - 3000:
                left += 1
            return len(self.requests) - left

class Solution:
    class TweetCounts:

        def __init__(self):
            self.tweets = defaultdict(list)

        def recordTweet(self, tweetName: str, time: int) -> None:
            bisect.insort(self.tweets[tweetName], time)

        def getTweetCountsPerFrequency(self, freq: str, tweetName: str, startTime: int, endTime: int) -> list[int]:
            if tweetName not in self.tweets:
                return []

            times = self.tweets[tweetName]
            idx_start = bisect.bisect_left(times, startTime)
            idx_end = bisect.bisect_right(times, endTime)
            times_in_range = times[idx_start:idx_end]

            if not times_in_range:
                return []

            if freq == "minute":
                interval = 60
            elif freq == "hour":
                interval = 3600
            else:  # "day"
                interval = 86400

            chunks = (endTime - startTime) // interval + 1
            result = [0] * chunks

            for t in times_in_range:
                chunk_index = (t - startTime) // interval
                result[chunk_index] += 1

            return result
